func capture(t *testing.T, source, pattern string) []string {
	t.Helper()
	m := regexp.MustCompile(pattern).FindStringSubmatch(source)
	if m == nil {
		t.Fatalf("could not find contract %s", pattern)
	}
	return m
}
func bakedLimit(t *testing.T, name string) int {
	t.Helper()
	source := string(read(t, filepath.Join(deployRoot(t), "internal/bootstrapstart/baked.go")))
	m := capture(t, source, `\b`+name+`\s*=\s*(\d+)(?:\s*<<\s*(\d+))?`)
	value, err := strconv.Atoi(m[1])
	if err != nil {
		t.Fatal(err)
	}
	if m[2] != "" {
		shift, err := strconv.Atoi(m[2])
		if err != nil {
			t.Fatal(err)
		}
		value <<= shift
	}
	return value
}

const (
	BakedDirectory = "/etc/terrascale-orchestrator/bootstrap"
	// RootChainFile is the root chain this controller adopted from the
	// cell's replicated record. The baked roots are only its genesis.
	RootChainFile = "/var/lib/terrascale-orchestrator-controller/trust/root-chain.json"
	// MaxRootFiles, MaxRootBytes, and MaxRootsTotal bound the baked trust-root
	// inventory shared with the offline anchor verifier.
	MaxRootFiles  = 16
	MaxRootBytes  = 16 << 10
	MaxRootsTotal = 64 << 10
	maxIdentity   = 4096
)

