func GuestBuild(ctx context.Context, repo string, o GuestBuildOptions, out io.Writer) (result error) {
	pin, e := client.LoadPin(filepath.Join(repo, "deploy/image/image-inputs.json"))
	if e != nil {
		return e
	}
	architecture, e := binaryArchitecture(o.Binary)
	if e != nil {
		return e
	}
	nativeArchitecture, e := binaryArchitecture(o.NativeVerifier)
	if e != nil {
		return e
	}
	if nativeArchitecture != architecture {
		return errors.New("native verifier and orchestrator architectures differ")
	}
	archive, e := pin.Archive(architecture)
	if e != nil {
		return e
	}
	if e = client.VerifyBinary(o.NetBirdBinary, archive.BinarySHA256, architecture); e != nil {
		return e
	}
	g, e := NewGuest(ctx, o.Image, false, nil)
	if e != nil {
		return e
	}
	defer func() { result = errors.Join(result, g.Close(result != nil)) }()
	if e = auditKernel(g, o.KernelRelease, o.Work, o.KernelOut, architecture, out); e != nil {
		return e
	}
	if e = requireDirectParents(g, path.Dir(Native)); e != nil {
		return e
	}
	if e = auditSystemd(g, o.Work, out); e != nil {
		return e
	}
	if e = auditTimeConfig(g, o.Work); e != nil {
		return e
	}
	if e = auditVolumeTools(g, o.Work, out); e != nil {
		return e
	}
	if e = auditSSHServer(g, o.Work, out); e != nil {
		return e
	}
	for _, p := range append([]string{Profile, Helper}, Dropins...) {
		if e = g.AssertAbsent(p, "runtime-priority profile artifact"); e != nil {
			return e
		}
	}
	for _, p := range []string{NetBird, NetBirdConfig, NetBirdPin, NetBirdFallback, "/var/lib/netbird"} {
		if e = g.AssertAbsent(p, "NetBird artifact"); e != nil {
			return e
		}
	}
	if e = g.AssertAbsent(App+"/host-enrollment-public.json", "host enrollment public bundle"); e != nil {
		return e
	}
	bootstrap := []string{Bootstrap + "/anchor.json", Bootstrap + "/identity.json", Bootstrap + "/host-enrollment-public.json", Bootstrap + "/operator-ssh-key.pub"}
	for i := range o.BootstrapRoots {
		bootstrap = append(bootstrap, fmt.Sprintf("%s/trust-roots/%03d.pem", Bootstrap, i+1))
	}
	for _, p := range bootstrap {
		if e = g.AssertAbsent(p, "bootstrap artifact"); e != nil {
			return e
		}
	}
	names, e := g.List(Bootstrap + "/trust-roots")
	if e != nil {
		return e
	}
	if len(names) > 0 {
		return errors.New("base image has a conflicting bootstrap trust-root directory")
	}
	for _, p := range []string{"/var/lib/terrascale-orchestrator", "/var/lib/terrascale-orchestrator-bootstrap", "/var/lib/terrascale-orchestrator-secrets", "/var/lib/terrascale-orchestrator-controller"} {
		if e = g.AssertAbsent(p, "orchestrator state root"); e != nil {
			return e
		}
	}
	kind, e := g.Kind("/srv")
	if e != nil {
		return e
	}
	if kind != "dir" {
		return errors.New("base /srv must be a direct root:root 0755 directory")
	}
	meta, e := g.Metadata("/srv")
	if e != nil {
		return e
	}
	if meta["st_uid"] != 0 || meta["st_gid"] != 0 || meta["st_mode"]&07777 != 0755 {
		return errors.New("base /srv must be a direct root:root 0755 directory")
	}
	for _, entry := range []struct{ p, label string }{{"/srv/ts-managed", "managed root"}, {VolumeState, "managed volume initialization state root"}, {OCIDevicePaths, "OCI device path rule"}} {
		if e = g.AssertAbsent(entry.p, entry.label); e != nil {
			return e
		}
	}
	uid, gid, accountFiles, e := accounts(g, o.Work, o.Sysusers, out)
	if e != nil {
		return e
	}
	kind, e = g.Kind(AppLib)
	if e != nil {
		return e
	}
	if kind == "" {
		if e = g.Directory(AppLib, 0, 0, 0755); e != nil {
			return e
		}
		meta, e = g.Metadata(AppLib)
		if e != nil {
			return e
		}
		if meta["st_uid"] != 0 || meta["st_gid"] != 0 || meta["st_mode"]&07777 != 0755 {
			return fmt.Errorf("installed application library parent has unexpected metadata: %s", AppLib)
		}
	}
	for _, directory := range []string{App, Bootstrap, Bootstrap + "/trust-roots", "/etc/sysusers.d", "/etc/systemd", "/etc/systemd/system", "/etc/systemd/timesyncd.conf.d", "/etc/systemd/system/system.slice.d", "/etc/systemd/system/terrascale-orchestrator-host.service.d", "/etc/systemd/system/terrascale-orchestrator-controller.service.d", "/etc/systemd/system/terrascale-orchestrator-host-setup.service.d", path.Dir(TimeDropin), "/usr/local/bin", path.Dir(Helper), path.Dir(Native), "/etc/udev", path.Dir(OCIDevicePaths), "/var/lib/terrascale-orchestrator-bootstrap"} {
		if e = g.Directory(directory, 0, 0, 0755); e != nil {
			return e
		}
	}
	if e = g.Directory("/etc/systemd/system/terrascale-netbird-enroll.service.d", 0, 0, 0755); e != nil {
		return e
	}
	for _, dir := range []struct {
		p       string
		u, g, m int
	}{{"/var/lib/terrascale-orchestrator", 0, 0, 0755}, {"/var/lib/terrascale-orchestrator/netbird-managed", 0, 0, 0700}, {"/var/lib/terrascale-orchestrator-secrets", uid, gid, 0700}, {"/var/lib/terrascale-orchestrator-controller", uid, gid, 0700}, {"/srv/ts-managed", 0, 2000, 0750}, {VolumeState, 0, 0, 0700}, {"/var/lib/netbird", 0, 0, 0700}} {
		if e = g.Directory(dir.p, dir.u, dir.g, dir.m); e != nil {
			return e
		}
	}
	pinWire, e := json.Marshal(pin)
	if e != nil {
		return e
	}
	pinPath := filepath.Join(o.Work, "netbird-pin.json")
	if e = os.WriteFile(pinPath, pinWire, 0644); e != nil {
		return e
	}
	uploads := []upload{{o.Sysusers, "/etc/sysusers.d/terrascale-orchestrator.conf", 0644}, {o.Profile, Profile, 0644}, {o.Binary, Helper, 0755}, {o.Binary, "/usr/local/bin/terrascale-orchestrator", 0755}, {o.NetBirdBinary, NetBird, 0755}, {o.NetBirdBinary, NetBirdFallback, 0755}, {pinPath, NetBirdPin, 0644}, {o.NetBirdConfig, NetBirdConfig, 0644}, {o.NativeVerifier, Native, 0755}, {o.Timesyncd, TimeConfig, 0644}, {filepath.Join(repo, "deploy/udev", path.Base(OCIDevicePaths)), OCIDevicePaths, 0644}}
	for _, name := range append(append([]string{"terrascale-orchestrator-bootstrap.service", "terrascale-orchestrator-controller-install.service", "terrascale-orchestrator-managed-host-start.service", "terrascale-orchestrator-managed-runtime.service", "terrascale-orchestrator-controller.service", "terrascale-orchestrator-host.service"}, NetBirdUnits...), HostUnitFiles...) {
		uploads = append(uploads, upload{filepath.Join(repo, "deploy/systemd", name), "/etc/systemd/system/" + name, 0644})
	}
	for _, name := range append(append([]string{}, SelfUpdateDropins...), SelfUpdateUnitFiles...) {
		uploads = append(uploads, upload{filepath.Join(repo, "deploy/systemd/selfupdate", name), "/etc/systemd/system/" + name, 0644})
	}
	for _, p := range Dropins {
		uploads = append(uploads, upload{filepath.Join(o.PriorityRoot, strings.TrimPrefix(p, "/")), p, 0644})
	}
	for i, source := range o.BootstrapRoots {
		uploads = append(uploads, upload{source, fmt.Sprintf("%s/trust-roots/%03d.pem", Bootstrap, i+1), 0444})
	}
	timeout := filepath.Join(o.Work, "terrascale-timeout.conf")
	if e = os.WriteFile(timeout, []byte("[Service]\nTimeoutStartSec=300s\n"), 0644); e != nil {
		return e
	}
	uploads = append(uploads, upload{timeout, TimeDropin, 0644})
	for _, u := range uploads {
		if e = g.Upload(u.source, u.destination, u.mode); e != nil {
			return e
		}
	}
	for _, u := range accountFiles {
		if e = g.Replace(u.source, u.destination, u.mode); e != nil {
			return e
		}
	}
	if e = installRuntime(ctx, g, architecture, o.Work, out); e != nil {
		return e
	}
	if e = installLinks(g, o.Work, repo, out); e != nil {
		return e
	}
	meta, e = g.Metadata("/srv/ts-managed")
	if e != nil {
		return e
	}
	if meta["st_uid"] != 0 || meta["st_gid"] != 2000 || meta["st_mode"]&07777 != 0750 {
		return errors.New("installed managed root has unexpected metadata")
	}
	return g.AssertFile(Native, 0, 0, 0755)
}

func GuestVerify(ctx context.Context, image string, expect []string, out io.Writer) (result error) {
	type expectation struct{ p, d string }
	var expected []expectation
	for _, item := range expect {
		p, d, ok := strings.CutLast(item, "=")
		if !ok || !strings.HasPrefix(p, "/") || !client.SHA256Pattern.MatchString(d) {
			return fmt.Errorf("invalid --expect GUEST_PATH=SHA256: %s", item)
		}
		expected = append(expected, expectation{p, d})
	}
	g, e := NewGuest(ctx, image, true, nil)
	if e != nil {
		return e
	}
	defer func() { result = errors.Join(result, g.Close(result != nil)) }()
	work, e := os.MkdirTemp("", "ts-image-verify-")
	if e != nil {
		return e
	}
	defer os.RemoveAll(work)
	for i, item := range expected {
		kind, e := g.Kind(item.p)
		if e != nil {
			return e
		}
		if kind != "file" {
			return fmt.Errorf("finished image lacks regular file: %s", item.p)
		}
		target := filepath.Join(work, strconv.Itoa(i))
		if _, e = g.Read(item.p, target); e != nil {
			return e
		}
		d, e := fileHash(target)
		if e != nil {
			return e
		}
		if d != item.d {
			return fmt.Errorf("finished image bytes differ from the expected SHA-256: %s", item.p)
		}
		if _, e = fmt.Fprintf(out, "image readback sha256=%s guest_path=%s\n", d, item.p); e != nil {
			return e
		}
	}
	return nil
}

func NormalizeTimesync(data []byte) ([]byte, error) {
	if len(data) == 0 || len(data) > 16384 {
		return nil, errors.New("timesyncd config must be between 1 byte and 16384 bytes")
	}
	if !utf8.Valid(data) {
		return nil, errors.New("timesyncd config must be UTF-8")
	}
	section := ""
	lists := map[string][]string{"NTP": {}, "FallbackNTP": {}}
	var preserved strings.Builder
	for i, raw := range strings.SplitAfter(string(data), "\n") {
		if raw == "" {
			continue
		}
		line := strings.TrimSpace(raw)
		if line == "" || strings.HasPrefix(line, "#") || strings.HasPrefix(line, ";") {
			preserved.WriteString(raw)
			continue
		}
		if strings.HasSuffix(line, "\\") {
			return nil, fmt.Errorf("timesyncd config line %d uses a continuation; use single-line server assignments", i+1)
		}
		if strings.HasPrefix(line, "[") && strings.HasSuffix(line, "]") {
			section = strings.TrimSpace(line[1 : len(line)-1])
			preserved.WriteString(raw)
			continue
		}
		key, value, ok := strings.Cut(line, "=")
		if !ok {
			return nil, fmt.Errorf("invalid timesyncd config line %d", i+1)
		}
		key = strings.TrimSpace(key)
		if section == "Time" && (key == "PollIntervalMinSec" || key == "PollIntervalMaxSec") {
			continue
		}
		if section == "Time" && (key == "NTP" || key == "FallbackNTP") {
			value = strings.TrimSpace(value)
			if strings.ContainsAny(value, "#;\"'\\") {
				return nil, fmt.Errorf("timesyncd config line %d uses unsupported inline comments, quoting, or escapes", i+1)
			}
			if value == "" {
				lists[key] = nil
			} else {
				lists[key] = append(lists[key], strings.Fields(value)...)
			}
			continue
		}
		preserved.WriteString(raw)
	}
	if len(lists["NTP"]) == 0 {
		return nil, errors.New("timesyncd config must contain nonempty [Time] NTP endpoints")
	}
	lab := regexp.MustCompile(`198\.19(?:\.[0-9]{1,3}){2}`)
	for key, list := range lists {
		for _, endpoint := range list {
			indices := lab.FindAllStringIndex(endpoint, -1)
			for _, idx := range indices {
				if (idx[0] == 0 || endpoint[idx[0]-1] < '0' || endpoint[idx[0]-1] > '9') && (idx[1] == len(endpoint) || endpoint[idx[1]] < '0' || endpoint[idx[1]] > '9') {
					return nil, fmt.Errorf("timesyncd config effective %s list must not contain the Firecracker lab NTP address range", key)
				}
			}
		}
	}
	normalized := preserved.String()
	if normalized != "" && !strings.HasSuffix(normalized, "\n") && !strings.HasSuffix(normalized, "\r") {
		normalized += "\n"
	}
	if section != "Time" {
		normalized += "[Time]\n"
	}
	normalized += "NTP=\nNTP=" + strings.Join(lists["NTP"], " ") + "\nFallbackNTP=\n"
	if len(lists["FallbackNTP"]) > 0 {
		normalized += "FallbackNTP=" + strings.Join(lists["FallbackNTP"], " ") + "\n"
	}
	normalized += "PollIntervalMinSec=32\nPollIntervalMaxSec=64\n"
	return []byte(normalized), nil
}

func requireDirectParents(g *Guest, p string) error {
	for _, parent := range []string{"/", "/usr", "/usr/local", "/usr/local/lib", AppLib} {
		kind, e := g.Kind(parent)
		if e != nil {
			return e
		}
		if kind == "" && parent == AppLib {
			continue
		}
		if kind != "dir" {
			if kind == "" {
				kind = "absent"
			}
			return fmt.Errorf("native verifier parent must be a root-owned nonwritable directory: %s (kind=%s)", parent, kind)
		}
		meta, e := g.Metadata(parent)
		if e != nil {
			return e
		}
		if meta["st_uid"] != 0 || meta["st_mode"]&022 != 0 {
			return fmt.Errorf("native verifier parent must be a root-owned nonwritable directory: %s (uid=%d gid=%d mode=0%o)", parent, meta["st_uid"], meta["st_gid"], meta["st_mode"]&07777)
		}
	}
	return g.AssertAbsent(p, "managed-material verifier directory")
}

func auditSystemd(g *Guest, work string, out io.Writer) error {
	status, e := g.Read("/var/lib/dpkg/status", filepath.Join(work, "base-dpkg-status"))
	if e != nil {
		return e
	}
	var versions []string
	for _, p := range packages(status) {
		if p["Package"] == "systemd" {
			versions = append(versions, p["Version"])
		}
	}
	if len(versions) != 1 || !strings.HasPrefix(versions[0], "255.") {
		return errors.New("base image must contain the audited Noble systemd 255 package")
	}
	host, e := g.exec(g.ctx, "", g.Env, "systemctl", "--version")
	if e != nil {
		return e
	}
	_, e = fmt.Fprintf(out, "offline unit enablement: guest systemd=%s host tool=%s\n", versions[0], strings.Split(host, "\n")[0])
	return e
}
func auditSSHServer(g *Guest, work string, out io.Writer) error {
	status, err := g.Read("/var/lib/dpkg/status", filepath.Join(work, "ssh-dpkg-status"))
	if err != nil {
		return err
	}
	installed := false
	for _, p := range packages(status) {
		installed = installed || p["Package"] == "openssh-server" && p["Status"] == "install ok installed"
	}
	if !installed {
		return errors.New("base image must contain the installed openssh-server package")
	}
	if err := g.AssertAbsent("/etc/ssh/sshd_not_to_be_run", "OpenSSH disable marker"); err != nil {
		return err
	}
	_, err = fmt.Fprintf(out, "offline OpenSSH server verified package=openssh-server unit=%s\n", SSHUnit)
	return err
}

func auditVolumeTools(g *Guest, work string, out io.Writer) error {
	status, e := g.Read("/var/lib/dpkg/status", filepath.Join(work, "volume-tools-dpkg-status"))
	if e != nil {
		return e
	}
	for name, version := range map[string]string{"e2fsprogs": "1.47.0-2.4~exp1ubuntu4.1", "util-linux": "2.39.3-9ubuntu6.6"} {
		var installed []map[string]string
		for _, p := range packages(status) {
			if p["Package"] == name && p["Status"] == "install ok installed" {
				installed = append(installed, p)
			}
		}
		if len(installed) != 1 || installed[0]["Version"] != version {
			observed := []string{}
			for _, p := range installed {
				observed = append(observed, p["Version"])
			}
			if len(observed) == 0 {
				observed = []string{"absent"}
			}
			return fmt.Errorf("host base image must contain pinned %s %s (observed %s)", name, version, strings.Join(observed, ", "))
		}
	}
	for _, p := range VolumeTools {
		current := p
		visited := map[string]bool{}
		resolved := false
		for range 40 {
			if visited[current] {
				return fmt.Errorf("host base image volume tool has a symlink loop: %s", p)
			}
			visited[current] = true
			kind, e := g.Kind(current)
			if e != nil {
				return e
			}
			if kind == "file" {
				meta, e := g.Metadata(current)
				if e != nil {
					return e
				}
				if meta["st_mode"]&0111 == 0 {
					return fmt.Errorf("host base image volume tool is not executable: %s", p)
				}
				resolved = true
				break
			}
			if kind != "symlink" {
				return fmt.Errorf("host base image is missing required volume tool: %s", p)
			}
			target, e := g.Call("readlink", current)
			if e != nil {
				return e
			}
			if target == "" || strings.ContainsRune(target, 0) {
				return fmt.Errorf("host base image volume tool has an invalid symlink: %s", p)
			}
			if !strings.HasPrefix(target, "/") {
				target = path.Join(path.Dir(current), target)
			}
			current = path.Clean(target)
			if !strings.HasPrefix(current, "/") || current == "/" || strings.HasPrefix(current, "/../") {
				return fmt.Errorf("host base image volume tool escapes its root: %s", p)
			}
		}
		if !resolved {
			return fmt.Errorf("host base image volume tool has too many symlinks: %s", p)
		}
	}
	_, e = fmt.Fprintf(out, "offline host volume tools verified packages=e2fsprogs,util-linux tools=%s\n", strings.Join(VolumeTools, ","))
	return e
}

func Execute(ctx context.Context, dir string, env []string, command ...string) (string, error) {
	if len(command) == 0 {
		return "", errors.New("empty command")
	}
	cmd := exec.CommandContext(ctx, command[0], command[1:]...)
	cmd.Dir = dir
	if env != nil {
		cmd.Env = env
	}
	cmd.WaitDelay = 2 * time.Second
	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
	cmd.Cancel = func() error { return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL) }
	var output, stderr bytes.Buffer
	cmd.Stdout = &output
	cmd.Stderr = &stderr
	if e := cmd.Run(); e != nil {
		action := strings.Join(command[:min(2, len(command))], " ")
		return "", fmt.Errorf("%s failed: %s: %w", action, strings.TrimSpace(stderr.String()+output.String()), e)
	}
	return strings.TrimSpace(output.String()), nil
}

func NewGuest(ctx context.Context, image string, readOnly bool, env []string) (*Guest, error) {
	errorsFile, e := os.CreateTemp("", "ts-guestfish-errors-")
	if e != nil {
		return nil, e
	}
	os.Remove(errorsFile.Name())
	g := &Guest{ctx: ctx, Env: env, Errors: errorsFile, directories: map[string]bool{}, exec: Execute}
	if g.Env == nil {
		g.Env = os.Environ()
	}
	args := []string{"--listen"}
	if readOnly {
		args = append(args, "--ro")
	}
	args = append(args, "--format=qcow2", "-a", image, "-i")
	cmd := exec.CommandContext(ctx, "guestfish", args...)
	cmd.Env = g.Env
	cmd.Stderr = errorsFile
	var stdout bytes.Buffer
	cmd.Stdout = &stdout
	cmd.WaitDelay = 2 * time.Second
	if e = cmd.Run(); e != nil {
		tail := g.ErrorTail()
		g.Errors.Close()
		return nil, fmt.Errorf("guestfish --listen failed: %s %s: %w", tail, strings.TrimSpace(stdout.String()), e)
	}
	match := regexp.MustCompile(`\bGUESTFISH_PID=(\d+)\b`).FindStringSubmatch(stdout.String())
	if match == nil {
		defer errorsFile.Close()
		return nil, fmt.Errorf("guestfish did not return a remote PID: %s; stderr: %s", strings.TrimSpace(stdout.String()), g.ErrorTail())
	}
	g.PID, e = strconv.Atoi(match[1])
	if e != nil {
		errorsFile.Close()
		return nil, e
	}
	g.Env = append(append([]string{}, g.Env...), "GUESTFISH_PID="+match[1])
	return g, nil
}

func (g *Guest) Call(command string, args ...string) (string, error) {
	argv := append([]string{"guestfish", "--remote", command}, args...)
	out, e := g.exec(g.ctx, "", g.Env, argv...)
	if e != nil {
		tail := g.ErrorTail()
		if tail == "" {
			tail = "(empty)"
		}
		return "", fmt.Errorf("%w; guestfish listener pid=%d state=%s; listener stderr: %s", e, g.PID, g.daemonState(), tail)
	}
	return out, nil
}
func (g *Guest) Close(ignoreError bool) error {
	cleanupCtx, cancel := context.WithTimeout(context.WithoutCancel(g.ctx), 10*time.Second)
	defer cancel()
	_, e := g.exec(cleanupCtx, "", g.Env, "guestfish", "--remote", "exit")
	closeErr := g.Errors.Close()
	if ignoreError {
		e = nil
	}
	return errors.Join(e, closeErr)
}

func (g *Guest) Kind(path string) (string, error) {
	if g.directories[path] {
		return "dir", nil
	}
	exists, e := g.Call("exists", path)
	if e != nil {
		return "", e
	}
	if exists == "false" {
		link, e := g.Call("is-symlink", path)
		if e != nil {
			return "", e
		}
		switch link {
		case "true":
			return "symlink", nil
		case "false":
			return "", nil
		}
		return "", fmt.Errorf("guestfish returned an invalid is-symlink result for %s: %s", path, link)
	}
	if exists != "true" {
		return "", fmt.Errorf("guestfish returned an invalid exists result for %s: %s", path, exists)
	}
	meta, e := g.Metadata(path)
	if e != nil {
		return "", e
	}
	switch meta["st_mode"] & syscall.S_IFMT {
	case syscall.S_IFLNK:
		return "symlink", nil
	case syscall.S_IFDIR:
		g.directories[path] = true
		return "dir", nil
	case syscall.S_IFREG:
		return "file", nil
	}
	return "other", nil
}
func (g *Guest) Metadata(path string) (map[string]int, error) {
	out, e := g.Call("lstatns", path)
	if e != nil {
		return nil, e
	}
	meta := map[string]int{}
	for line := range strings.SplitSeq(out, "\n") {
		key, value, ok := strings.Cut(line, ":")
		if !ok || !strings.HasPrefix(key, "st_") {
			continue
		}
		n, e := strconv.Atoi(strings.TrimSpace(value))
		if e != nil {
			return nil, e
		}
		meta[key] = n
	}
	for _, key := range []string{"st_mode", "st_uid", "st_gid", "st_nlink"} {
		if _, ok := meta[key]; !ok {
			return nil, fmt.Errorf("guestfish omitted %s for %s", key, path)
		}
	}
	return meta, nil
}
func (g *Guest) Read(path, target string) ([]byte, error) {
	if _, e := g.Call("download", path, target); e != nil {
		return nil, e
	}
	return os.ReadFile(target)
}
func (g *Guest) List(path string) ([]string, error) {
	kind, e := g.Kind(path)
	if e != nil {
		return nil, e
	}
	if kind == "" {
		return []string{}, nil
	}
	if kind != "dir" {
		return nil, fmt.Errorf("expected guest directory: %s", path)
	}
	out, e := g.Call("ls", path)
	if e != nil {
		return nil, e
	}
	if out == "" {
		return []string{}, nil
	}
	names := strings.Split(out, "\n")
	for _, name := range names {
		if name == "" || name == "." || name == ".." || strings.Contains(name, "/") {
			return nil, fmt.Errorf("unsafe directory entry under %s", path)
		}
	}
	return names, nil
}
func (g *Guest) AssertAbsent(path, label string) error {
	kind, e := g.Kind(path)
	if e != nil {
		return e
	}
	if kind != "" {
		return fmt.Errorf("base image has a conflicting %s: %s", label, path)
	}
	return nil
}
